// Each flak mounting's training arc, and where it has to be laid up to clear
// her and where it cannot fire low, as [angle, arc, lift, mask], in the order
// her aa.guns list them -- surveyed off the model for each ship apart, since
// the Scheer's extra flak is in the way of her sister's guns' bearings.
const surveyedAA = (guns, arcs) => {
  let k = 0;
  const out = guns.map((g) => ({ ...g, mounts: g.mounts.map((m) => {
    const [angle, arc, lift, mask] = arcs[k++];
    return { ...m, angle, arc, ...(lift && { lift }), ...(mask && { mask }) };
  }) }));
  if (k !== arcs.length) throw new Error(`${k} flak mountings, ${arcs.length} surveyed`);
  return out;
};
