    // forward, Caesar aft -- twelve 15 cm, eight in four twin turrets and four
    // in single shielded mountings on her beam, and her 10.5 cm flak, on a
    // hull built for thirty-one knots. With her sister she sank the carrier
    // Glorious off Norway in June 1940; she was sunk off the North Cape on 26
    // December 1943 by Duke of York and her destroyers, after a running fight
    // in the dark in which her speed had nearly carried her clear.
    //
    // She is drawn from the owner's sculpts of her (see scharnhorst.js) as she
