        total: 72,
        min: { fighters: 0, dive: 0, torpedo: 0 },
        max: { fighters: 72, dive: 72, torpedo: 72 },
        minStrike: 0,
        // Eighteen Zeros, twenty-seven Suiseis and twenty-seven Kates: the
