/**
 * How much more a hull takes than her datasheet number, all of them alike.
 *
 * Ships went down too quickly for an action to be fought: a few good salvoes
 * and the thing was over. A real hull soaked up an astonishing amount of
 * punishment above the waterline -- what sank ships was water, not hit
 * points -- so every class carries this much more structure, and the sea
 * coming in through her holes is left to do what it did.
 */
//
// Raised again from 1.8: battles were still decided by the first few good
// salvoes. Every hull now takes about a quarter more before she is wrecked.
export const HULL_TOUGHNESS = 2.3;
// Not a submarine: a pressure hull split by a charge is a boat lost, however
// much else she could have taken.
for (const c of Object.values(SHIP_CLASSES)) if (!c.dive) c.hp = Math.round(c.hp * HULL_TOUGHNESS);

export const SHIP_ORDER = ['fletcher', 'matsu', 'yukikaze', 'guangzhou', 'sovremenny', 'slava', 'burke', 'cleveland', 'hipper', 'spee', 'scheer', 'takao', 'maya', 'baltimore', 'ticonderoga', 'leviathan', 'u48',
  'surcouf', 'sboat', 'morosini', 'richelieu', 'scharnhorst', 'hagen', 'bismarck', 'tirpitz', 'soyuz', 'hood', 'kgv', 'rodney', 'massachusetts', 'iowa', 'missouri', 'nimitz', 'kongo', 'fuso', 'mutsu', 'yamato', 'musashi',
  'grafzeppelin', 'hornet', 'enterprise', 'shokaku', 'shinano', 'agincourt', 'liberty', 'higgins'];

/**
 * The yard's list split by era, for the choice the ship icon offers before the
 * yard opens: the Great War's hulls, the Second World War's, or the missile
 * age's. A hull is modern if she
 * sails as she was after 1945 (Missouri as recommissioned in 1991, the Nimitz, Leviathan, the
 * Ticonderoga, the Guangzhou, the Sovremenny, the Slava and the Arleigh Burke); everything
 * else is WWII.
 */
export const MODERN_SHIPS = new Set(['guangzhou', 'sovremenny', 'slava', 'burke', 'ticonderoga', 'leviathan', 'missouri', 'nimitz']);
// And the Great War's: the dreadnoughts that sailed as they were before 1919.
export const WWI_SHIPS = new Set(['agincourt']);
// And the ships that are not warships at all, whatever war they sailed in:
// the merchantmen and the transports, in a yard of their own beside the
// Modern one.
export const CIVIL_SHIPS = new Set(['liberty', 'higgins']);
export const WWI_ORDER = SHIP_ORDER.filter((id) => WWI_SHIPS.has(id));
export const WWII_ORDER = SHIP_ORDER.filter((id) => !MODERN_SHIPS.has(id) && !WWI_SHIPS.has(id) && !CIVIL_SHIPS.has(id));
export const MODERN_ORDER = SHIP_ORDER.filter((id) => MODERN_SHIPS.has(id));
export const CIVIL_ORDER = SHIP_ORDER.filter((id) => CIVIL_SHIPS.has(id));

/**
 * The hulls in the Premium Equipment store, and not in the yard's list: a
 * captain finds them under Premium Equipment, Ships. Every one of them sails
 * as any other hull does once she is in a fleet (see PLAYABLE).
 */
export const PREMIUM_ORDER = ['tillman'];

/** Every hull a fleet can have in it: the yard's and the store's. */
export const PLAYABLE = [...SHIP_ORDER, ...PREMIUM_ORDER];

export function getClass(id) {
  return SHIP_CLASSES[id] || SHIP_CLASSES.fletcher;
}

/** Total number of barrels that can bear, used for the UI salvo readout. */
export function totalGuns(cls) {
  return cls.turrets.reduce((n, t) => n + t.guns, 0);
}

export const SHELL_TYPES = { AP, HE };
